import {createSoundPanel} from './sound-panel.js';
import {esc,format,downloadName} from './ui-utils.js';
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
// The expanded view controls the shared audio engine. Opening/closing never restarts a track.
export function createMusicPlayer({audio,getTrack,getTracks,cover,downloadUrl,onToggle,onSelect,onNext,onPrevious,onFavorite,isFavorite,toast}){
 const dialog=document.createElement('dialog');dialog.id='music-player';dialog.className='music-dialog';dialog.setAttribute('aria-labelledby','now-title');
 dialog.innerHTML=`<div class="now-top"><div><span class="now-live"></span><span class="eyebrow">EM REPRODUÇÃO</span></div><button class="icon-button" data-now-close aria-label="Recolher player">${icon('chevron')}</button></div><div class="now-layout"><div class="now-art-column"><div class="now-art" id="now-art"></div><div class="now-format"><span id="now-format">ÁUDIO ORIGINAL</span><span class="now-quality">Sem reconversão</span></div></div><div class="now-track-meta"><p class="eyebrow" id="now-version"></p><div class="now-heading"><h2 id="now-title"></h2><button class="icon-button" data-now-favorite aria-label="Favoritar música" aria-pressed="false">${icon('heart')}</button></div><button class="text-button now-title-more" data-now-title-more aria-expanded="false" aria-controls="now-title" hidden>Título completo</button><p id="now-artists"></p></div><div class="now-controls"><div class="now-spectrum"><canvas id="now-spectrum" aria-label="Visualização do áudio" role="img"></canvas><button class="text-button spectrum-enable" data-now-spectrum>Ativar visualização de áudio</button></div><div class="now-progress"><label class="sr-only" for="now-seek">Posição da música</label><input id="now-seek" type="range" min="0" max="1" step=".1" value="0"><div><span id="now-elapsed">0:00</span><span id="now-duration">0:00</span></div></div><div class="now-transport"><button class="icon-button" data-now-shuffle aria-label="Reprodução aleatória" aria-pressed="false">${icon('shuffle')}</button><button class="icon-button" data-now-prev aria-label="Faixa anterior">${icon('prev')}</button><button class="now-play" data-now-play aria-label="Reproduzir">${icon('play')}</button><button class="icon-button" data-now-next aria-label="Próxima faixa">${icon('next')}</button><button class="icon-button" data-now-repeat aria-label="Repetir faixa" aria-pressed="false">${icon('repeat')}</button></div><div class="now-options"><label class="now-volume">${icon('volume')}<span class="sr-only">Volume</span><input id="now-volume" type="range" min="0" max="1" step=".01" value="1"></label><label><span class="sr-only">Velocidade da música</span><select id="now-speed">${[.75,1,1.25,1.5,2].map(x=>`<option value="${x}" ${x===1?'selected':''}>${x}×</option>`).join('')}</select></label><a class="icon-button" id="now-download" aria-label="Baixar áudio">${icon('download')}</a><a class="icon-button" id="now-detail" aria-label="Abrir detalhes e comentários">${icon('comment')}</a></div></div><div class="now-panels"><div class="now-panel-tabs" role="tablist" aria-label="Opções do player"><button type="button" id="now-queue-tab" data-now-queue-tab role="tab" aria-selected="true" aria-controls="now-queue-panel">${icon('list')}<span>Fila</span></button><button type="button" id="now-sound-tab" class="sound-open" data-now-sound role="tab" aria-selected="false" tabindex="-1" aria-expanded="false" aria-controls="sound-panel">${icon('sliders')}<span>Som e transição</span></button></div><p id="sound-summary" class="sound-summary">Crossfade · 4 s</p><p id="now-transition" class="transition-status" role="status" hidden></p><div id="sound-panel" role="tabpanel" aria-labelledby="now-sound-tab" hidden></div><section id="now-queue-panel" role="tabpanel" aria-labelledby="now-queue-tab"><div class="now-queue-heading"><h3>A seguir</h3><span id="now-queue-count"></span></div><div class="now-queue" id="now-queue"></div></section></div></div>`;
 document.body.append(dialog);
 const $=id=>dialog.querySelector('#'+id),button=name=>dialog.querySelector(`[data-now-${name}]`);
 let previousFocus=null,lastTrack='',lastQueue='',analyser=null,frame=0,spectrum=false;
 const sound=createSoundPanel($('sound-panel'),audio,{onChange(){syncSoundSummary();}});
 function syncSoundSummary(){const s=audio.settings;$('sound-summary').textContent=(s.crossfade?`Crossfade · ${s.crossfade} s`:'Sem transição')+(s.enabled?' · EQ ligado':'');dialog.querySelector('.now-quality').textContent=s.enabled?'Som personalizado':'Áudio original';}
 function setPanel(panel){const soundOpen=panel==='sound';$('sound-panel').hidden=!soundOpen;$('now-queue-panel').hidden=soundOpen;button('sound').setAttribute('aria-expanded',String(soundOpen));for(const [tab,selected]of [[button('sound'),soundOpen],[button('queue-tab'),!soundOpen]]){tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;}if(soundOpen)sound.sync();}
 button('sound').onclick=()=>setPanel('sound');button('queue-tab').onclick=()=>setPanel('queue');
 dialog.querySelector('.now-panel-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const panel=e.key==='Home'?'queue':e.key==='End'?'sound':$('sound-panel').hidden?'sound':'queue';setPanel(panel);button(panel==='sound'?'sound':'queue-tab').focus();});
 button('title-more').onclick=()=>{const expanded=button('title-more').getAttribute('aria-expanded')!=='true';button('title-more').setAttribute('aria-expanded',String(expanded));button('title-more').textContent=expanded?'Recolher título':'Título completo';$('now-title').classList.toggle('title-expanded',expanded);};
 audio.addEventListener('soundchange',syncSoundSummary);audio.addEventListener('transitionchange',e=>{$('now-transition').hidden=!e.detail;$('now-transition').textContent=e.detail?`Misturando faixas · ${e.detail.duration.toFixed(1).replace('.',',')} s`:'';});syncSoundSummary();
 function sync(){
  const t=getTrack();if(!t)return;
  if(lastTrack!==t.id+':'+t.updated_at){lastTrack=t.id+':'+t.updated_at;$('now-art').innerHTML=cover(t);$('now-title').textContent=t.title;button('title-more').hidden=t.title.length<90;button('title-more').setAttribute('aria-expanded','false');button('title-more').textContent='Título completo';$('now-title').classList.remove('title-expanded');$('now-artists').textContent=t.artists;$('now-version').textContent=t.remix||'KYROSHIX RELEASES';$('now-detail').href='#faixa/'+encodeURIComponent(t.id);$('now-download').href=downloadUrl(t);$('now-download').download=downloadName(t);$('now-format').textContent=(t.audio_path?.split('.').pop()||'ÁUDIO').toUpperCase()+' · ORIGINAL';}
  button('play').innerHTML=icon(audio.paused?'play':'pause');button('play').setAttribute('aria-label',audio.paused?'Reproduzir':'Pausar');button('favorite').setAttribute('aria-pressed',String(isFavorite(t.id)));button('repeat').setAttribute('aria-pressed',String(audio.loop));button('shuffle').setAttribute('aria-pressed',document.getElementById('shuffle').getAttribute('aria-pressed'));$('now-volume').value=audio.volume;$('now-speed').value=audio.playbackRate;
  const tracks=getTracks(),key=tracks.map(x=>x.id+':'+x.title).join('|')+':'+t.id;
  if(key!==lastQueue){lastQueue=key;const index=tracks.findIndex(x=>x.id===t.id),ordered=[...tracks.slice(index+1),...tracks.slice(0,index)];$('now-queue-count').textContent=ordered.length+' faixas';$('now-queue').innerHTML=ordered.map(x=>`<button class="now-queue-item" data-now-select="${esc(x.id)}"><span class="mini-cover">${cover(x)}</span><span><strong>${esc(x.title)}</strong><small>${esc(x.artists)}</small></span><span>${format(x.duration)}</span>${icon('play')}</button>`).join('')||'<p class="subtle">Você está na última faixa da seleção.</p>';}
  dialog.querySelector('.now-queue-heading h3').textContent=button('shuffle').getAttribute('aria-pressed')==='true'?'Na sua seleção':'A seguir';progress();
 }
 function progress(){const duration=Number.isFinite(audio.duration)?audio.duration:getTrack()?.duration||0;$('now-seek').max=duration||1;$('now-seek').value=audio.currentTime;$('now-seek').style.setProperty('--played',`${duration?audio.currentTime/duration*100:0}%`);$('now-seek').setAttribute('aria-valuetext',`${format(audio.currentTime)} de ${format(duration)}`);$('now-elapsed').textContent=format(audio.currentTime);$('now-duration').textContent=format(duration);}
 function drawSpectrum(){cancelAnimationFrame(frame);if(!dialog.open||!spectrum||document.hidden)return;const canvas=$('now-spectrum'),width=Math.max(1,canvas.clientWidth),height=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==width*dpr||canvas.height!==height*dpr){canvas.width=width*dpr;canvas.height=height*dpr;}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);const bins=new Uint8Array(analyser.frequencyBinCount);analyser.getByteFrequencyData(bins);const n=56,gap=4,bw=Math.max(1,(width-gap*(n-1))/n),gradient=ctx.createLinearGradient(0,0,width,0);gradient.addColorStop(0,'#9486ff');gradient.addColorStop(1,'#f394ca');ctx.fillStyle=gradient;for(let i=0;i<n;i++){const bin=Math.floor((i/n)**1.65*(bins.length*.72)),value=audio.paused?0:bins[bin],h=Math.max(2,value/255*(height-8));ctx.beginPath();ctx.roundRect(i*(bw+gap),(height-h)/2,bw,h,Math.min(2,bw/2));ctx.fill();}if(!audio.paused&&!matchMedia('(prefers-reduced-motion: reduce)').matches)frame=requestAnimationFrame(drawSpectrum);}
 async function enableSpectrum(){try{analyser=await audio.getAnalyser();spectrum=true;button('spectrum').hidden=true;drawSpectrum();}catch{toast('A visualização não está disponível neste navegador.');}}
 button('spectrum').onclick=enableSpectrum;
 function open(panel){if(!getTrack())return;previousFocus=document.activeElement;sync();if(panel)setPanel(panel);if(!dialog.open)dialog.showModal();document.body.classList.add('music-expanded');button('close').focus();if(!audio.paused&&!spectrum)enableSpectrum();else drawSpectrum();}
 function close(){dialog.close();}
 button('close').onclick=close;
 dialog.addEventListener('close',()=>{document.body.classList.remove('music-expanded');cancelAnimationFrame(frame);previousFocus?.focus?.();});
 button('play').onclick=()=>{if(!spectrum)enableSpectrum();onToggle();};button('prev').onclick=onPrevious;button('next').onclick=onNext;button('favorite').onclick=()=>{onFavorite(getTrack().id);sync();};
 button('shuffle').onclick=()=>{document.getElementById('shuffle').click();sync();};button('repeat').onclick=()=>{document.getElementById('repeat').click();sync();};
 $('now-seek').addEventListener('input',e=>{if(Number.isFinite(audio.duration)){audio.currentTime=Number(e.target.value);progress();}});
 $('now-volume').addEventListener('input',e=>{audio.volume=Number(e.target.value);const v=document.getElementById('volume');v.value=audio.volume;v.dispatchEvent(new Event('input'));});
 $('now-speed').addEventListener('change',e=>{audio.playbackRate=Number(e.target.value);audio.preservesPitch=true;});
 $('now-detail').onclick=()=>dialog.close();
 $('now-queue').addEventListener('click',e=>{const item=e.target.closest('[data-now-select]');if(item)onSelect(item.dataset.nowSelect);});
 for(const event of ['loadedmetadata','durationchange','play','pause','emptied','volumechange','ratechange'])audio.addEventListener(event,()=>{if(dialog.open)sync();if(spectrum)drawSpectrum();});
 audio.addEventListener('timeupdate',()=>{if(dialog.open)progress();});document.addEventListener('visibilitychange',drawSpectrum);
 dialog.addEventListener('keydown',e=>{if(/INPUT|SELECT|BUTTON|TEXTAREA|A/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Space'){e.preventDefault();onToggle();}if(e.key==='ArrowRight')audio.currentTime=Math.min(audio.duration||Infinity,audio.currentTime+5);if(e.key==='ArrowLeft')audio.currentTime=Math.max(0,audio.currentTime-5);});
 return {open,sync,close};
}
